    view.unmount();
  }
});

it("shows uptime in seconds, minutes and days", () => {
  for (const [uptime, label] of [
    [42_000, "Up 42s"],
    [5 * 60_000, "Up 5m"],
    [(2 * 24 + 3) * 3_600_000, "Up 2d 3h"],
