  fireEvent.click(screen.getByRole("button", { name: "Advance rundown" }));
  await waitFor(() =>
    expect(flight.goFlight).toHaveBeenCalledWith("radio-demo"),
  );
  expect(await screen.findByRole("alert")).toHaveTextContent(
